script.pine:
//@version=5
indicator("ATR % of close", overlay=false)

len = input.int(14, "ATR length", minval=1)

// ATR by Wilder's smoothing of True Range
atrVal = ta.rma(ta.tr, len)
atrPct = atrVal / close * 100

plot(atrPct, "ATR % of close", color=color.teal, linewidth=2)

var table t = table.new(position.top_right, 2, 1, border_width=1)
table.cell(t, 0, 0, "ATR " + str.tostring(len) + " %", text_color=color.white, bgcolor=color.gray)
table.cell(t, 1, 0, str.tostring(atrPct, "#.##") + "%", text_color=color.white)

//@version=5
indicator("252-bar high line", overlay=true)
n = input.int(252, "Lookback bars", minval=1)
hh = ta.highest(high, n)
var line hiLine = line.new(bar_index, hh, bar_index, hh, extend=extend.right, color=color.red, width=2)
if not na(hh)
    line.set_xy1(hiLine, bar_index - n, hh)
    line.set_xy2(hiLine, bar_index, hh)
plot(hh, "Highest high", color=color.new(color.red, 100))

//@version=5
indicator("100-bar high & low labels", overlay=true)

n = input.int(100, "Lookback bars", minval=2)

hh = ta.highest(high, n)
ll = ta.lowest(low, n)

// offset (in bars back) of where the extreme occurred inside the window
hiOff = ta.highestbars(high, n)
loOff = ta.lowestbars(low, n)

var label hiLab = label.new(bar_index, hh, "", style=label.style_label_down, color=color.red, textcolor=color.white, size=size.small)
var label loLab = label.new(bar_index, ll, "", style=label.style_label_up, color=color.green, textcolor=color.white, size=size.small)

if not na(hh)
    label.set_xy(hiLab, bar_index + nz(hiOff), hh)
    label.set_text(hiLab, str.tostring(hh, format.mintick))

if not na(ll)
    label.set_xy(loLab, bar_index + nz(loOff), ll)
    label.set_text(loLab, str.tostring(ll, format.mintick))

plot(hh, "Highest high", color=color.new(color.red, 100))
plot(ll, "Lowest low", color=color.new(color.green, 100))
